    false, // flat fields 3, 4, 5, 6, 7, 8 are out
    false, // flat fields 3, 4, 5, 6, 7, 8 are out
    false, // flat fields 3, 4, 5, 6, 7, 8 are out
    false, // flat fields 3, 4, 5, 6, 7, 8 are out
    false, // flat fields 3, 4, 5, 6, 7, 8 are out
    false, // nested field 9 is in
    true, // nested field 9 is in
    true, // nested field 9 is in
    true, // nested field 9 is in
    true, // nested field 9 is in
    true, // nested field 10 is out
    false, // nested field 10 is out
    false, // nested field 10 is out
    false, // nested field 10 is out
    false, true, true, true, true, // nested field 11 is in
    true };
    assertArrayEquals(expected, options.getInclude());
}

