@Test
public void testProcessingTimestampisPassedToNFA() throws Exception {
    final NFA<Event> nfa = NFACompiler.compileFactory(Pattern.<Event>begin("begin"), true).createNFA();
    final NFA<Event> spyNFA = spy(nfa);
    try (OneInputStreamOperatorTestHarness<Event, Map<String, List<Event>>> harness = CepOperatorTestUtilities.getCepTestHarness(createOperatorForNFA(spyNFA).build())) {
        long timestamp = 5;
        harness.open();
        harness.setProcessingTime(timestamp);
        StreamRecord<Event> event = event().withTimestamp(3).asStreamRecord();
        harness.processElement(event);
        verify(spyNFA).process(any(SharedBufferAccessor.class), any(NFAState.class), eq(event.getValue()), eq(timestamp), any(AfterMatchSkipStrategy.class), any(TimerService.class));
    }
}

