    when(taskManagerGateway.cancelTask(any(ExecutionAttemptID.class), any(Time.class))).thenReturn(CompletableFuture.completedFuture(Acknowledge.get()));
    final SimpleSlotProvider slotProvider = new SimpleSlotProvider(jid, parallelism, taskManagerGateway);
    final CheckpointCoordinatorConfiguration checkpointCoordinatorConfiguration = new CheckpointCoordinatorConfiguration(10L, 100000L, 1L, 3, CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION, true, false);
    final ExecutionGraph graph = createSampleGraph(jid, (eg) -> new RestartIndividualStrategy(eg) {

        @Override
        protected void performExecutionVertexRestart(ExecutionVertex vertexToRecover, long globalModVersion) {
        }
    }, // twice restart, no delay
    new TestRestartStrategy(2, false), slotProvider, parallelism);
    graph.start(mainThreadExecutor);
    final List<ExecutionJobVertex> allVertices = new ArrayList<>(graph.getAllVertices().values());
    final StandaloneCheckpointIDCounter standaloneCheckpointIDCounter = new StandaloneCheckpointIDCounter();
    graph.enableCheckpointing(checkpointCoordinatorConfiguration.getCheckpointInterval(), checkpointCoordinatorConfiguration.getCheckpointTimeout(), checkpointCoordinatorConfiguration.getMinPauseBetweenCheckpoints(), checkpointCoordinatorConfiguration.getMaxConcurrentCheckpoints(), checkpointCoordinatorConfiguration.getCheckpointRetentionPolicy(), allVertices, allVertices, allVertices, Collections.emptyList(), standaloneCheckpointIDCounter, new StandaloneCompletedCheckpointStore(1), new MemoryStateBackend(), new CheckpointStatsTracker(1, allVertices, checkpointCoordinatorConfiguration, UnregisteredMetricGroups.createUnregisteredTaskMetricGroup()), false);
    final CheckpointCoordinator checkpointCoordinator = graph.getCheckpointCoordinator();
    final ExecutionJobVertex ejv = graph.getVerticesTopologically().iterator().next();
    final ExecutionVertex vertex1 = ejv.getTaskVertices()[0];
    final ExecutionVertex vertex2 = ejv.getTaskVertices()[1];
    graph.scheduleForExecution();
    assertEquals(JobStatus.RUNNING, graph.getState());
    verify(taskManagerGateway, timeout(verifyTimeout).times(parallelism)).submitTask(any(TaskDeploymentDescriptor.class), any(Time.class));
    // switch all executions to running
    for (ExecutionVertex executionVertex : graph.getAllExecutionVertices()) {
        executionVertex.getCurrentExecutionAttempt().switchToRunning();
    }
    // wait for a first checkpoint to be triggered
    verify(taskManagerGateway, timeout(verifyTimeout).times(3)).triggerCheckpoint(eq(vertex1.getCurrentExecutionAttempt().getAttemptId()), any(JobID.class), anyLong(), anyLong(), any(CheckpointOptions.class), any(Boolean.class));
    verify(taskManagerGateway, timeout(verifyTimeout).times(3)).triggerCheckpoint(eq(vertex2.getCurrentExecutionAttempt().getAttemptId()), any(JobID.class), anyLong(), anyLong(), any(CheckpointOptions.class), any(Boolean.class));
    assertEquals(3, checkpointCoordinator.getNumberOfPendingCheckpoints());
    long checkpointToAcknowledge = standaloneCheckpointIDCounter.getLast();
    checkpointCoordinator.receiveAcknowledgeMessage(new AcknowledgeCheckpoint(graph.getJobID(), vertex1.getCurrentExecutionAttempt().getAttemptId(), checkpointToAcknowledge));
    Map<Long, PendingCheckpoint> oldPendingCheckpoints = new HashMap<>(3);
    for (PendingCheckpoint pendingCheckpoint : checkpointCoordinator.getPendingCheckpoints().values()) {
        assertFalse(pendingCheckpoint.isDiscarded());
        oldPendingCheckpoints.put(pendingCheckpoint.getCheckpointId(), pendingCheckpoint);
    }
    // let one of the vertices fail - this should trigger the failing of not acknowledged pending checkpoints
    vertex1.getCurrentExecutionAttempt().fail(new Exception("test failure"));
    for (PendingCheckpoint pendingCheckpoint : oldPendingCheckpoints.values()) {
        if (pendingCheckpoint.getCheckpointId() == checkpointToAcknowledge) {
            assertFalse(pendingCheckpoint.isDiscarded());
        } else {
            assertTrue(pendingCheckpoint.isDiscarded());
        }
    }
}

