    createBarrier(1, 1), createBarrier(1, 2), /* 5 */
    createBuffer(2, PAGE_SIZE), createBuffer(1, PAGE_SIZE), /* 7 */
    createBarrier(1, 0), /* 8 */
    createBuffer(0, PAGE_SIZE), createBuffer(2, PAGE_SIZE), // aborted on last barrier
    /* 10 */
    createBarrier(2, 0), createBarrier(2, 2), /* 12 */
    createBuffer(0, PAGE_SIZE), createBuffer(2, PAGE_SIZE), /* 14 */
    createCancellationBarrier(2, 1), // successful checkpoint
    /* 15 */
    createBuffer(2, PAGE_SIZE), createBuffer(1, PAGE_SIZE), /* 17 */
    createBarrier(3, 1), createBarrier(3, 2), createBarrier(3, 0), // abort on first barrier
    /* 20 */
    createBuffer(0, PAGE_SIZE), createBuffer(1, PAGE_SIZE), /* 22 */
    createCancellationBarrier(4, 1), createBarrier(4, 2), /* 24 */
    createBuffer(0, PAGE_SIZE), /* 25 */
    createBarrier(4, 0), // another successful checkpoint
    /* 26 */
    createBuffer(0, PAGE_SIZE), createBuffer(1, PAGE_SIZE), createBuffer(2, PAGE_SIZE), /* 29 */
    createBarrier(5, 2), createBarrier(5, 1), createBarrier(5, 0), /* 32 */
    createBuffer(0, PAGE_SIZE), createBuffer(1, PAGE_SIZE), // abort multiple cancellations and a barrier after the cancellations
    /* 34 */
    createCancellationBarrier(6, 1), createCancellationBarrier(6, 2), /* 36 */
    createBarrier(6, 0), /* 37 */
    createBuffer(0, PAGE_SIZE) };
    MockInputGate gate = new MockInputGate(PAGE_SIZE, 3, Arrays.asList(sequence));
    BarrierBuffer buffer = createBarrierHandler(gate);
