    startTs = System.nanoTime();
    check(sequence[12], buffer.getNextNonBlocked(), PAGE_SIZE);
    verify(toNotify, times(1)).abortCheckpointOnBarrier(eq(2L), any(CheckpointDeclineOnCancellationBarrierException.class));
